// Read-only access to the library generated by scripts/library/build.ts.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { THEMES, type Theme } from './themes';

export interface LibraryNote {
  slug: string;
  title: string;
  kind: 'book' | 'concept';
  theme: string;
  excerpt: string;
  html: string;
  links: string[];
  backlinks: string[];
  related: string[];
  book: { title: string; author: string; year: number | null; publisher: string | null } | null;
}

interface LibraryData {
  themes: string[];
  report: { books: number; concepts: number; links: number };
  notes: LibraryNote[];
}

let cache: (LibraryData & { bySlug: Map<string, LibraryNote> }) | null = null;

export function library() {
  if (!cache) {
    const data = JSON.parse(readFileSync(join(process.cwd(), '.generated/library.json'), 'utf8')) as LibraryData;
    const unknown = data.themes.filter((t) => !THEMES.some((th) => th.name === t));
    if (unknown.length) throw new Error(`Temáticas sin color en src/lib/themes.ts: ${unknown.join(', ')}`);
    cache = { ...data, bySlug: new Map(data.notes.map((n) => [n.slug, n])) };
  }
  return cache;
}

export const themeOf = (note: Pick<LibraryNote, 'theme'>): Theme => THEMES.find((t) => t.name === note.theme)!;

export const byTitle = (a: { title: string }, b: { title: string }) => a.title.localeCompare(b.title, 'es');
